export function parseCsv(text) {
  if (typeof text !== "string") {
    throw new TypeError("CSV input must be a string");
  }

  if (text.startsWith("\uFEFF")) {
    text = text.slice(1);
  }
  if (text.length === 0) {
    return [];
  }

  const rows = [];
  let row = [];
  let field = "";
  let state = "start";
  let recordPending = true;

  const finishField = () => {
    row.push(field);
    field = "";
    state = "start";
  };

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];

    if (state === "quoted") {
      if (character === '"') {
        if (text[index + 1] === '"') {
          field += '"';
          index += 1;
        } else {
          state = "closed";
        }
      } else {
        field += character;
      }
      continue;
    }

    if (character === ",") {
      finishField();
      recordPending = true;
      continue;
    }

    if (character === "\n" || character === "\r") {
      finishField();
      rows.push(row);
      row = [];
      recordPending = false;
      if (character === "\r" && text[index + 1] === "\n") {
        index += 1;
      }
      continue;
    }

    if (state === "closed") {
      throw new SyntaxError("Unexpected character after closing quote");
    }
    if (character === '"') {
      if (state !== "start") {
        throw new SyntaxError("Unexpected quote in unquoted field");
      }
      state = "quoted";
    } else {
      field += character;
      state = "bare";
    }
    recordPending = true;
  }

  if (state === "quoted") {
    throw new SyntaxError("Unclosed quoted field");
  }
  if (recordPending) {
    finishField();
    rows.push(row);
  }
  return rows;
}

import test from "node:test";
import assert from "node:assert/strict";
import { parseCsv } from "../src/csv.mjs";

test("empty input and exactly one leading BOM do not create a record", () => {
  assert.deepEqual(parseCsv(""), []);
  assert.deepEqual(parseCsv("\uFEFF"), []);
  assert.deepEqual(parseCsv("\uFEFF\uFEFF"), [["\uFEFF"]]);
});

test("record separators preserve empty records without adding a trailing record", () => {
  assert.deepEqual(parseCsv("a\r\nb\rc\nd\n"), [["a"], ["b"], ["c"], ["d"]]);
  assert.deepEqual(parseCsv("a\n\n"), [["a"], [""]]);
  assert.deepEqual(parseCsv("\n"), [[""]]);
});

test("quoted fields preserve whitespace and original newlines and decode doubled quotes", () => {
  assert.deepEqual(parseCsv(" x , y "), [[" x ", " y "]]);
  assert.deepEqual(parseCsv('"a,b","say ""hi""","x\r\ny\rz"'), [
    ["a,b", 'say "hi"', "x\r\ny\rz"],
  ]);
});

test("invalid input type and invalid quote placement fail explicitly", () => {
  assert.throws(() => parseCsv(null), TypeError);
  assert.throws(() => parseCsv('"open'), SyntaxError);
  assert.throws(() => parseCsv('bare"quote'), SyntaxError);
  assert.throws(() => parseCsv('"closed"x'), SyntaxError);
});
